package pricing                    // core: no time, os, net, database/sql
type Inputs struct { Cart Cart; TaxRate int; PromoActive bool; Now time.Time }
type Quote  struct { Subtotal, Tax, Total int64; ExpiresAt time.Time }
func Price(in Inputs) Quote {      // pure: same inputs, same quote
    sub := int64(0)
    for _, it := range in.Cart.Items { sub += it.UnitCents * int64(it.Qty) }
    if in.PromoActive { sub = sub * 90 / 100 }
    tax := sub * int64(in.TaxRate) / 10000
    return Quote{Subtotal: sub, Tax: tax, Total: sub + tax,
                 ExpiresAt: in.Now.Add(15 * time.Minute)}
}
// shell: handler loads, calls Price, saves -- no business rule belongs here.
